// ── التقدم: التمارين المنجزة ──
function _wqDone(){ try{ return JSON.parse(localStorage.getItem('hh_wq_done')||'{}')||{}; }catch(e){ return {}; } }
function _wqSaveDone(m){ try{ localStorage.setItem('hh_wq_done', JSON.stringify(m)); }catch(e){} }
function wqToggleEx(exId, btn){
  var m=_wqDone();
  if(m[exId]){ delete m[exId]; } else { m[exId]=Date.now(); }
  _wqSaveDone(m);
  var on=!!m[exId];
  btn.classList.toggle('wq-ex-on', on);
  btn.innerHTML = on ? '✓ أُنجز التمرين' : 'أنجزت هذا التمرين؟';
  var hdr=document.getElementById('wq-prog-num');
  if(hdr) hdr.textContent = Object.keys(m).length;
}

// ── الصلاحية: الفصل الأول وجناح الانطلاق مجاناً، والبقية بالتسجيل ──
function _wqAllowed(secId){
  if(typeof _hhSpkAccess!=='undefined' && _hhSpkAccess===true) return true;
  if(typeof hhIsAdmin==='function' && hhIsAdmin()) return true;
  return [0,1,2,3,4,5,6].indexOf(Number(secId))!==-1;
}

// ═══ فتح الاستوديو ═══
function hhWathiqOpen(){
  try{ document.body.classList.add('hh-immersive'); }catch(e){}
  try{ if(typeof hhSpkCheckAccess==='function') hhSpkCheckAccess(); }catch(e){}
  var old=document.getElementById('hh-wathiq'); if(old) old.remove();
  var ov=document.createElement('div'); ov.id='hh-wathiq';
  ov.style.cssText='position:fixed;inset:0;background:linear-gradient(180deg,#0E1B2E,#16283F 60%,#0E1B2E);z-index:999976;overflow-y:auto;direction:rtl;font-family:Cairo,Tajawal,sans-serif;';
  var doneCount=Object.keys(_wqDone()).length;

  var chips = WQ_MAP.chapters.map(function(c){
    var open=_wqAllowed(c.id);
    return '<div onclick="wqOpenSec('+c.id+')" style="cursor:pointer;background:'+(open?'linear-gradient(165deg,#1C3450,#12233A)':'rgba(255,255,255,.03)')+';border:1.5px solid '+(open?'#D4BC85':'rgba(212,188,133,.25)')+';border-radius:15px;padding:13px 11px;text-align:center;position:relative;transition:transform .15s;" onmouseover="this.style.transform=\'translateY(-3px)\'" onmouseout="this.style.transform=\'\'">' 
      +'<span style="position:absolute;top:8px;left:9px;font-size:.62rem;color:'+(open?'#8FD0C9':'#5A6B80')+';font-weight:800;">'+(open?(c.n===1?'معاينة مجانية':'مفتوح'):'🔒 بالتسجيل')+'</span>'
      +'<span style="display:inline-flex;width:46px;height:46px;border-radius:50%;background:'+(open?'radial-gradient(circle at 35% 30%,#F5E6C4,#B8924A 75%)':'rgba(255,255,255,.06)')+';border:2px solid '+(open?'#FDF3DD':'rgba(212,188,133,.3)')+';align-items:center;justify-content:center;margin-bottom:7px;">'
      +'<svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="'+(open?'#16283F':'#5A6B80')+'" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+WQ_ICON[c.icon]+'</svg></span>'
      +'<div style="color:#D4BC85;font-size:.66rem;font-weight:800;">المحطة '+c.n+'</div>'
      +'<div style="color:#F2F6FB;font-weight:800;font-size:.92rem;margin:2px 0;">'+c.t+'</div>'
      +'<div style="color:#8FA3BC;font-size:.68rem;">'+c.sub+'</div>'
      +'</div>';
  }).join('');

  function row(list){
    return list.map(function(it){
      var open=_wqAllowed(it.id);
      return '<button onclick="wqOpenSec('+it.id+')" style="all:unset;cursor:pointer;background:'+(open?'rgba(212,188,133,.08)':'rgba(255,255,255,.03)')+';border:1px solid '+(open?'rgba(212,188,133,.55)':'rgba(212,188,133,.2)')+';border-radius:12px;padding:9px 13px;box-sizing:border-box;">'
        +'<div style="color:#F2F6FB;font-weight:800;font-size:.8rem;">'+(open?'':'🔒 ')+it.t+'</div>'
        +(it.sub?'<div style="color:#8FA3BC;font-size:.66rem;margin-top:1px;">'+it.sub+'</div>':'')
        +'</button>';
    }).join('');
  }

  ov.innerHTML =
    '<div style="max-width:960px;margin:0 auto;padding:16px 16px 60px;">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:14px;">'
    +  '<div style="display:flex;gap:7px;">'
    +    '<button onclick="wqBack()" style="background:rgba(212,188,133,.12);border:1px solid rgba(212,188,133,.5);border-radius:9px;height:32px;padding:0 13px;color:#F5E6C4;font-weight:800;font-size:.8rem;cursor:pointer;font-family:Cairo;">‹ رجوع</button>'
    +    '<button onclick="wqHome()" style="background:rgba(212,188,133,.12);border:1px solid rgba(212,188,133,.5);border-radius:9px;width:32px;height:32px;color:#F5E6C4;cursor:pointer;"><svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><path d="M12 3l9 7v11h-6v-7H9v7H3V10l9-7z"/></svg></button>'
    +  '</div>'
    +  '<div style="text-align:left;color:#8FA3BC;font-size:.7rem;">تمارين منجزة: <b id="wq-prog-num" style="color:#8FD0C9;font-size:.9rem;">'+doneCount+'</b></div>'
    +'</div>'

    +'<div style="text-align:center;padding:18px 12px 20px;background:radial-gradient(ellipse at top, rgba(212,188,133,.1), transparent 65%);border:1px solid rgba(212,188,133,.35);border-radius:20px;margin-bottom:16px;position:relative;overflow:hidden;">'
    +  '<div style="color:#D4BC85;font-size:.72rem;letter-spacing:3px;font-weight:800;">البرنامج التدريبي المعتمد</div>'
    +  '<div style="color:#F2F6FB;font-weight:800;font-size:1.7rem;margin:5px 0 3px;">الواثــق المُـلـهِـم</div>'
    +  '<div style="color:#8FA3BC;font-size:.82rem;">دليلك الشامل في مهارات الإلقاء والتحدث أمام الجمهور</div>'
    +  '<div style="display:inline-flex;gap:8px;align-items:center;margin-top:11px;background:rgba(20,35,55,.7);border:1px solid #D4BC85;border-radius:99px;padding:6px 18px;flex-wrap:wrap;justify-content:center;">'
    +    '<span style="color:#8FD0C9;font-weight:800;font-size:.78rem;">جسد واثق</span><span style="color:#D4BC85;">+</span>'
    +    '<span style="color:#8FD0C9;font-weight:800;font-size:.78rem;">صوت واضح</span><span style="color:#D4BC85;">+</span>'
    +    '<span style="color:#8FD0C9;font-weight:800;font-size:.78rem;">كلام مرتب</span><span style="color:#D4BC85;">=</span>'
    +    '<span style="color:#F5E6C4;font-weight:800;font-size:.8rem;">متحدث مُلهِم</span>'
    +  '</div>'
    +  '<div style="color:#5A7089;font-size:.68rem;margin-top:8px;">إعداد المدرب: أحمد الحلحلي · رحلة ثلاثة أشهر</div>'
    +'</div>'

    +'<div style="color:#D4BC85;font-weight:800;font-size:.85rem;margin:2px 0 8px;">محطات الرحلة الست</div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:9px;margin-bottom:16px;">'+chips+'</div>'

    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:start;">'
    +'<div><div style="color:#D4BC85;font-weight:800;font-size:.85rem;margin-bottom:7px;">جناح الانطلاق</div>'
    +'<div style="display:grid;gap:7px;">'+row(WQ_MAP.intro.items)+'</div></div>'
    +'<div><div style="color:#D4BC85;font-weight:800;font-size:.85rem;margin-bottom:7px;">كنوز الواثق</div>'
    +'<div style="display:grid;gap:7px;">'+row(WQ_MAP.treasures.items)+'</div>'
    +'<div style="color:#D4BC85;font-weight:800;font-size:.85rem;margin:12px 0 7px;">ملف المدرب وولي الأمر</div>'
    +'<div style="display:grid;gap:7px;">'+row(WQ_MAP.trainer)+'</div></div>'
    +'</div>'
    +'</div>';
  document.body.appendChild(ov);
}

function wqBack(){
  try{ if(!document.getElementById('hh-wq-reader') && document.getElementById('hh-wathiq')) document.body.classList.remove('hh-immersive'); }catch(e){}
  var r=document.getElementById('hh-wq-reader');
  if(r){ r.remove(); return; }
  var w=document.getElementById('hh-wathiq'); if(w) w.remove();
}
function wqHome(){
  try{ document.body.classList.remove('hh-immersive'); }catch(e){}
  ['hh-wq-reader','hh-wathiq'].forEach(function(id){ var e=document.getElementById(id); if(e) e.remove(); });
  if(typeof hhCloseLeaders==='function'){ var l=document.getElementById('hh-leaders'); if(l) l.remove(); }
  if(typeof showScreen==='function') showScreen('screen-menu');
}

// ═══ قارئ القسم: فقرات ذكية + صناديق تمارين ═══
function wqOpenSec(id){
  if(!_wqAllowed(id)){
    if(typeof toast==='function') toast('هذه المحطة تُفتح بالتسجيل في البرنامج','warn');
    if(typeof hhSpkRequestAccess==='function') setTimeout(hhSpkRequestAccess, 700);
    return;
  }
  var txt = WQ_TEXT[String(id)]||'';
  var meta = null;
  WQ_MAP.chapters.forEach(function(c){ if(c.id===id) meta=c; });
  var title = meta ? ('المحطة '+meta.n+': '+meta.t) : '';
  if(!meta){
    [].concat(WQ_MAP.intro.items, WQ_MAP.treasures.items, WQ_MAP.trainer).forEach(function(it){ if(it.id===id) title=it.t; });
  }
  var extras = meta ? meta.extra : [];

  var old=document.getElementById('hh-wq-reader'); if(old) old.remove();
  var ov=document.createElement('div'); ov.id='hh-wq-reader';
  ov.style.cssText='position:fixed;inset:0;background:linear-gradient(180deg,#0E1B2E,#16283F);z-index:999977;overflow-y:auto;direction:rtl;font-family:Cairo,Tajawal,sans-serif;';

  var body = wqRender(txt, id);
  extras.forEach(function(x){
    body += '<div style="height:1px;background:linear-gradient(90deg,transparent,#D4BC85,transparent);margin:22px 0;"></div>' + wqRender(WQ_TEXT[String(x)]||'', x);
  });

  ov.innerHTML =
    '<div style="max-width:820px;margin:0 auto;padding:14px 16px 70px;">'
    +'<div style="position:sticky;top:0;background:linear-gradient(180deg,#0E1B2E 75%,transparent);padding:8px 0 12px;z-index:5;display:flex;justify-content:space-between;align-items:center;gap:8px;">'
    +  '<div style="display:flex;gap:7px;">'
    +    '<button onclick="wqBack()" style="background:rgba(212,188,133,.12);border:1px solid rgba(212,188,133,.5);border-radius:9px;height:32px;padding:0 13px;color:#F5E6C4;font-weight:800;font-size:.8rem;cursor:pointer;font-family:Cairo;">‹ رجوع</button>'
    +    '<button onclick="wqHome()" style="background:rgba(212,188,133,.12);border:1px solid rgba(212,188,133,.5);border-radius:9px;width:32px;height:32px;color:#F5E6C4;cursor:pointer;"><svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><path d="M12 3l9 7v11h-6v-7H9v7H3V10l9-7z"/></svg></button>'
    +  '</div>'
    +  '<div style="color:#D4BC85;font-weight:800;font-size:.95rem;text-align:left;">'+title+'</div>'
    +'</div>'
    + body
    +'</div>';
  document.body.appendChild(ov);
  ov.scrollTop=0;
}

function wqEsc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function wqRender(txt, secId){
  var EX_RE = /(تمرين|تدريب|نشاط|تحدي|مهمة|طبق الآن|قيّم)/;
  var paras = txt.split(/\n\s*\n/);
  var out=''; var exN=0;
  paras.forEach(function(p, i){
    p = p.trim(); if(!p) return;
    var lines = p.split('\n').map(function(l){return l.trim();}).filter(Boolean);
    var isEx = EX_RE.test(p.slice(0,42));
    var html = lines.map(function(l){
      if(/^○/.test(l)) return '<div style="display:flex;gap:8px;align-items:flex-start;margin:4px 0;"><span style="color:#D4BC85;flex-shrink:0;">✦</span><span>'+wqEsc(l.replace(/^○\s*/,''))+'</span></div>';
      if(/^[-–]/.test(l)) return '<div style="display:flex;gap:8px;align-items:flex-start;margin:3px 0;"><span style="color:#8FD0C9;flex-shrink:0;">•</span><span>'+wqEsc(l.replace(/^[-–]\s*/,''))+'</span></div>';
      return '<div>'+wqEsc(l)+'</div>';
    }).join('');
    var isHead = lines.length===1 && lines[0].length<60 && !/[.،]$/.test(lines[0]) && i<paras.length-1;
    if(isEx){
      exN++;
      var exId = 'wq_'+secId+'_'+exN;
      var done = !!_wqDone()[exId];
      out += '<div style="background:linear-gradient(165deg,rgba(212,188,133,.13),rgba(212,188,133,.05));border:1.5px solid #D4BC85;border-radius:15px;padding:13px 15px;margin:13px 0;">'
        +'<div style="display:flex;align-items:center;gap:7px;margin-bottom:7px;"><span style="width:26px;height:26px;border-radius:8px;background:linear-gradient(135deg,#F5E6C4,#B8924A);display:inline-flex;align-items:center;justify-content:center;color:#16283F;"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M13 2L4 14h6l-1 8 9-12h-6l1-8z"/></svg></span><span style="color:#F5E6C4;font-weight:800;font-size:.82rem;">محطة تطبيق</span></div>'
        +'<div style="color:#DCE6F2;font-size:.86rem;line-height:2;">'+html+'</div>'
        +'<button onclick="wqToggleEx(\''+exId+'\',this)" class="'+(done?'wq-ex-on':'')+'" style="margin-top:9px;background:'+(done?'linear-gradient(135deg,#8FD0C9,#5BA8A0)':'rgba(212,188,133,.15)')+';border:1px solid #D4BC85;border-radius:99px;padding:6px 16px;color:'+(done?'#0E1B2E':'#F5E6C4')+';font-weight:800;font-size:.74rem;cursor:pointer;font-family:Cairo;">'+(done?'✓ أُنجز التمرين':'أنجزت هذا التمرين؟')+'</button>'
        +'</div>';
    } else if(isHead){
      out += '<div style="color:#D4BC85;font-weight:800;font-size:1.05rem;margin:18px 0 7px;display:flex;align-items:center;gap:9px;"><span style="width:7px;height:7px;background:#D4BC85;transform:rotate(45deg);flex-shrink:0;"></span>'+wqEsc(lines[0])+'</div>';
    } else {
      out += '<div style="background:rgba(255,255,255,.035);border:1px solid rgba(143,163,188,.2);border-radius:13px;padding:11px 14px;margin:9px 0;color:#DCE6F2;font-size:.87rem;line-height:2.05;">'+html+'</div>';
    }
  });
  return out;
}
